css:
.fx-mqh{min-height:100vh;display:grid;align-content:center;gap:2.4em;overflow:hidden;padding:3em 0;background:var(--surface)}
.fx-mqh .rw{overflow:hidden;white-space:nowrap}
.fx-mqh .tr{display:inline-flex;width:max-content;animation:fxmqh calc(30s/var(--speed)) linear infinite}
.fx-mqh .rw.rev .tr{animation-direction:reverse;animation-duration:calc(38s/var(--speed))}
.fx-mqh .rw:hover .tr,.fx-mqh .rw:focus-within .tr{animation-play-state:paused}
.fx-mqh .g{display:inline-flex;align-items:center;gap:.3em;padding-right:.3em;font:600 clamp(3.2em,12vw,9em)/1 var(--font-heading);letter-spacing:-.02em}
.fx-mqh .g span{padding:0 .1em}
.fx-mqh .g .o{color:transparent;-webkit-text-stroke:max(1.5px,.015em) var(--text)}
.fx-mqh .rw.rev .g span:not(.o){color:var(--primary)}
.fx-mqh .g b{font-size:.4em;color:var(--accent);padding:0 .35em;font-weight:400}
.fx-mqh .mid{display:flex;justify-content:space-between;align-items:center;gap:1.5em;flex-wrap:wrap;width:min(1100px,90%);margin:0 auto}
.fx-mqh .mid p{max-width:40ch;opacity:.7}
.fx-mqh .mid a{padding:.85em 1.5em;border-radius:99px;background:var(--text);color:var(--surface);font-weight:700;text-decoration:none;transition:transform calc(.25s/var(--speed))}.fx-mqh .mid a:hover{transform:scale(1.05)}.fx-mqh .mid a:focus-visible{outline:2px solid var(--accent);outline-offset:3px}
@keyframes fxmqh{to{transform:translateX(-50%)}}
@media(prefers-reduced-motion:reduce){.fx-mqh .tr{animation:none}.fx-mqh .mid a{transition:none}}

/* touch: :hover mirrored as .is-tap */
.fx-mqh .rw.is-tap .tr{animation-play-state:paused}
.fx-mqh .mid a.is-tap{transform:scale(1.05)}
